// ==== Changes list hydration ====
// Populate #changes-list on the Changes page from site/log.json (landed
// ticks, newest first), so the list and the export buttons above have real
// data instead of an empty list. Guarded: a missing element, failed fetch,
// or unexpected schema leaves the page untouched.
function formatWhen(when) {
  const raw = String(when || '');
  if (!raw) return '';
  let iso = raw;
  // Normalize tick_id form (2026-11-14-221144Z) to ISO before parsing.
  const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})-(\d{2})(\d{2})(\d{2})Z$/);
  if (m) iso = m[1] + '-' + m[2] + '-' + m[3] + 'T' + m[4] + ':' + m[5] + ':' + m[6] + 'Z';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return raw;
  try {
    return d.toLocaleString(undefined, { timeZone: 'UTC', dateStyle: 'medium', timeStyle: 'short' }) + ' UTC';
  } catch (err) {
    return raw;
  }
}

function pathLink(path) {
  const a = document.createElement('a');
  a.href = 'https://github.com/s04/momento/blob/main/' + encodeURI(path);
  a.textContent = path;
  return a;
}

function hydrateChangesList() {
  const list = document.getElementById('changes-list');
  if (!list) return;
  fetch('log.json')
    .then((r) => r.json())
    .then((data) => {
      if (!Array.isArray(data)) return;
      const ticks = data.filter((t) => t && t.state === 'landed');
      if (!ticks.length) return;
      list.textContent = '';
      ticks.forEach((t) => {
        const li = document.createElement('li');
        // Accept both snake_case and camelCase log.json schemas.
        const when = t.run_at || t.runAt || t.tick_id || t.tickId || '';
        const paths = t.changed_paths || t.changedPaths || '';
        const whenSpan = document.createElement('span');
        whenSpan.className = 'change-when';
        whenSpan.textContent = formatWhen(when);
        li.appendChild(whenSpan);
        li.appendChild(document.createTextNode(' — '));
        const pathList = String(paths).trim().split(/\s+/).filter(Boolean);
        if (pathList.length) {
          pathList.forEach((p, i) => {
            if (i) li.appendChild(document.createTextNode(' '));
            li.appendChild(pathLink(p));
          });
        } else {
          li.appendChild(document.createTextNode('no paths recorded'));
        }
        list.appendChild(li);
      });
    })
    .catch(() => {
      // log.json unavailable; leave the list as-is
    });
}
